// What the ports share: names, and colours by slot or role.
import { oklabToHex, toSrgbGamut, type Vec3 } from "../../src/core/color";
import { ROLES, type Flavour, type Role } from "../../src/core/palette";

/** Generated files, by path under palettes/. */
export type Files = Record<string, string>;

export const AUTHOR = "madoromi";
export const HEADER = "generated by `bun run palettes`; edit scripts/ports instead";
export const themeName = (f: Flavour) => `madoromi ${f.id}`;
export const slug = (f: Flavour) => `madoromi-${f.id}`;
export const isDark = (f: Flavour) => f.mode === "yoru";

export const hex = (f: Flavour, key: string) => f.colours[key].hex;
export const role = (f: Flavour, r: Role) => hex(f, ROLES[r]);

/** `t` of a colour washed over the paper, for tints where a port has no transparency. */
export function wash(f: Flavour, key: string, t: number): string {
  const a = f.colours.kami.lab;
  const b = f.colours[key].lab;
  return oklabToHex(toSrgbGamut([0, 1, 2].map((i) => a[i] + (b[i] - a[i]) * t) as Vec3));
}

/** #rrggbbaa. */
export const alpha = (hex: string, a: number) => hex + Math.round(a * 255).toString(16).padStart(2, "0");
